Here is a simple Python program that simulates an animal's habitat:

```Python
class Habitat:
    def __init__(self):
        self.animals = []
        self.food = 100
        self.water = 100
        self.temperature = 20
        self.light = "day"

    def add_animal(self, name):
        self.animals.append({"name": name})

    def remove_animal(self, name):
        for animal in self.animals:
            if animal["name"] == name:
                self.animals.remove(animal)
                return

    def check_habitat(self):
        print(f"Temperature: {self.temperature} degrees Celsius")
        print(f"Light: {self.light}")
        print(f"Food available: {self.food} units")
        print(f"Water available: {self.water} units")

    def update_temperature(self, temperature):
        self.temperature = temperature

    def update_light(self, light):
        self.light = light

    def feed_animal(self, name):
        if len([animal for animal in self.animals if animal["name"] == name]) > 0:
            print(f"Feeding {name}...")
            self.food -= 10
            if self.food < 0:
                self.food = 0
            print(f"Food left: {self.food} units")
        else:
            print("No animal with that name found.")

    def water_animal(self, name):
        if len([animal for animal in self.animals if animal["name"] == name]) > 0:
            print(f"Watring {name}...")
            self.water -= 10
            if self.water < 0:
                self.water = 0
            print(f"Water left: {self.water} units")
        else:
            print("No animal with that name found.")

    def simulate(self):
        while True:
            print("\nOptions:")
            print("1. Add animal")
            print("2. Remove animal")
            print("3. Check habitat conditions")
            print("4. Update temperature")
            print("5. Update light")
            print("6. Feed animal")
            print("7. Water animal")
            print("8. Quit")
            choice = input("Enter your choice: ")
            if choice == "1":
                name = input("Enter the animal's name: ")
                self.add_animal(name)
            elif choice == "2":
                name = input("Enter the animal's name: ")
                self.remove_animal(name)
            elif choice == "3":
                self.check_habitat()
            elif choice == "4":
                temperature = int(input("Enter new temperature: "))
                self.update_temperature(temperature)
            elif choice == "5":
