Here is a simple function in C++ that calculates the area of a triangle given its three vertices.

```cpp
#include <cmath>

struct Point {
    double x, y;
};

double calculateArea(Point a, Point b, Point c) {
    // Calculate the lengths of the sides
    double ab = sqrt(pow(b.x - a.x, 2) + pow(b.y - a.y, 2));
    double bc = sqrt(pow(c.x - b.x, 2) + pow(c.y - b.y, 2));
    double ca = sqrt(pow(a.x - c.x, 2) + pow(a.y - c.y, 2));

    // Calculate the semi-perimeter
    double s = (ab + bc + ca) / 2;

    // Apply Heron's formula to calculate the area
    return sqrt(s * (s - ab) * (s - bc) * (s - ca));
}

int main() {
    Point a = {0, 0};
    Point b = {3, 0};
    Point c = {0, 4};

    double area = calculateArea(a, b, c);

    std::cout << "The area of the triangle is: " << area << std::endl;

    return 0;
}
```

This function calculates the length of each side of the triangle using the distance formula, then uses Heron's formula to calculate the area. Note that this assumes that the points are in a two-dimensional space (i.e., they have x and y coordinates).

