Here is a simple console-based flight booking system in Python:

```Python
class Flight:
    def __init__(self, flight_number, origin, destination):
        self.flight_number = flight_number
        self.origin = origin
        self.destination = destination
        self.passengers = []

class Passenger:
    def __init__(self, name):
        self.name = name

class BookingSystem:
    def __init__(self):
        self.flights = {}

    def add_flight(self, flight):
        self.flights[flight.flight_number] = flight

    def book_flight(self, flight_number, passenger_name):
        if flight_number in self.flights:
            flight = self.flights[flight_number]
            new_passenger = Passenger(passenger_name)
            flight.passengers.append(new_passenger)
            print(f"{passenger_name} has booked {flight.flight_number} from {flight.origin} to {flight.destination}.")
        else:
            print("No such flight exists.")

    def list_flights(self):
        for flight in self.flights.values():
            print(f"Flight Number: {flight.flight_number}, Origin: {flight.origin}, Destination: {flight.destination}")

def main():
    booking_system = BookingSystem()

    while True:
        print("\n1. Add Flight")
        print("2. Book Flight")
        print("3. List Flights")
        print("4. Quit")

        choice = input("Choose an option: ")

        if choice == "1":
            flight_number = input("Enter the flight number: ")
            origin = input("Enter the origin city: ")
            destination = input("Enter the destination city: ")
            new_flight = Flight(flight_number, origin, destination)
            booking_system.add_flight(new_flight)
        elif choice == "2":
            flight_number = input("Enter the flight number to book: ")
            passenger_name = input("Enter your name: ")
            booking_system.book_flight(flight_number, passenger_name)
        elif choice == "3":
            booking_system.list_flights()
        elif choice == "4":
            break
        else:
            print("Invalid option. Please choose a valid option.")

if __name__ == "__main__":
    main()

```

